from decimal import Decimal, ROUND_HALF_UP

def compact(n: int) -> str:
    if n < 1000:
        return str(n)

    units = [('bi', 1_000_000_000), ('mi', 1_000_000), ('mil', 1_000)]

    for unit_name, unit_val in units:
        if n >= unit_val:
            # Calculate value and round half up to 1 decimal place
            val = Decimal(n) / Decimal(unit_val)
            rounded = val.quantize(Decimal('0.1'), rounding=ROUND_HALF_UP)

            # Convert to string and strip trailing '.0'
            s = f"{rounded:f}"
            if s.endswith('.0'):
                s = s[:-2]

            return f"{s} {unit_name}"

    return str(n)
