import heapq

def build_order(deps: dict[str, list[str]]) -> list[str]:
    adj = {}
    in_degree = {}
    all_nodes = set(deps.keys())

    for node, neighbors in deps.items():
        if node not in in_degree:
            in_degree[node] = 0
        for neighbor in neighbors:
            all_nodes.add(neighbor)
            if neighbor not in adj:
                adj[neighbor] = []
            adj[neighbor].append(node)
            if node not in in_degree:
                in_degree[node] = 0
            in_degree[node] = in_degree.get(node, 0)

            # Correcting logic: The input 'deps' maps item -> its dependencies.
            # This means if A depends on B, B must come BEFORE A.
            # So B is a prerequisite for A. Edge: B -> A.

    # Re-evaluating structure based on requirement:
    # "an order in which every item comes after the items it depends on"
    # deps = {item: [dependencies]}
    # means dependency -> item is the directed edge.

    graph = {}
    in_degree = {node: 0 for node in all_nodes}

    for item, requirements in deps.items():
        for req in requirements:
            # req must come before item. Edge: req -> item
            if req not in graph:
                graph[req] = []
            graph[req].append(item)
            in_degree[item] += 1

    # Kahn's algorithm with a Min-Heap for lexicographical order
    ready_queue = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(ready_queue)

    order = []
    while ready_queue:
        u = heapq.heappop(ready_queue)
        order.append(u)

        if u in graph:
            for v in graph[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    heapq.heappush(ready_queue, v)

    if len(order) != len(all_nodes):
        raise ValueError("Cycle detected")

    return order
