import copy

def deep_merge(base: dict, override: dict) -> dict:
    def merge_recursive(b, o):
        if isinstance(b, dict) and isinstance(o, dict):
            new_dict = copy.deepcopy(b)
            for key, value in o.items():
                if value is None:
                    if key in new_dict:
                        del new_dict[key]
                elif key in new_dict:
                    new_dict[key] = merge_recursive(new_dict[key], value)
                else:
                    new_dict[key] = copy.deepcopy(value)
            return new_dict
        else:
            return copy.deepcopy(o)

    # Start with a deep copy of base to ensure no shared references
    result = copy.deepcopy(base)

    for key, value in override.items():
        if value is None:
            if key in result:
                del result[key]
        elif key in result and isinstance(result[key], dict) and isinstance(value, dict):
            result[key] = merge_recursive(result[key], value)
        else:
            result[key] = copy.deepcopy(value)

    return result
