    for node, neighbors in deps.items():
        for dep in neighbors:
            adj[dep].append(node)
            in_degree[node] += 1

    # Min-heap for lexicographical order (alphabetically smallest first)
    queue = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(queue)

    result = []
    while queue:
        u = heapq.heappop(queue)
        result.append(u)

        for v in adj[u]:
