import copy

def deep_merge(base: dict, override: dict) -> dict:
    def merge_recursive(base_val, over_val):
        if isinstance(over_val, dict) and isinstance(base_val, dict):
            new_dict = {}
            # Get all keys from both
            all_keys = set(base_val.keys()) | set(over_val.keys())
            for key in all_keys:
                if key in over_val:
                    if over_val[key] is None:
                        continue
                    if key in base_val:
                        new_dict[key] = merge_recursive(base_val[key], over_val[key])
                    else:
                        new_dict[key] = copy.deepcopy(over_val[key])
                elif key in base_val:
                    new_dict[key] = copy.deepcopy(base_val[key])
            return new_dict
        else:
            return copy.deepcopy(over_val)

    # Start with a shallow copy of base to begin building the result
    result = copy.deepcopy(base)

    for key, value in override.items():
        if value is None:
            if key in result:
                del result[key]
        elif key in result and isinstance(result[key], dict) and isinstance(value, dict):
            result[key] = merge_recursive(result[key], value)
        else:
            result[key] = copy.deepcopy(value)

    return result
