import heapq

def build_order(deps: dict[str, list[str]]) -> list[str]:
    adj = {}
    in_degree = {}
    all_nodes = set()

    # Initialize all nodes from keys and values to ensure all items are included
    for u, dependencies in deps.items():
        all_nodes.add(u)
        for v in dependencies:
            all_nodes.add(v)

    for node in all_nodes:
        adj[node] = []
        in_degree[node] = 0

    # Build graph: dependency -> item (edges go from dependency to the node that needs it)
    for u, dependencies in deps.items():
        for v in dependencies:
            adj[v].append(u)
            in_degree[u] += 1

    # Priority queue for Kahn's algorithm (min-heap for alphabetical order)
    queue = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(queue)

    result = []
    while queue:
        u = heapq.heappop(queue)
        result.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(queue, v)

    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected")

    return result
